/* Presentation and persistence; business mutations are exclusively in GemGame. */
'use strict';
const {CFG}=GemGame, $=s=>document.querySelector(s), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), I=Art.icon, G=Art.gem;
const KEY='gem-shop-v1-slot-', OWNER='tab-'+Date.now()+'-'+Math.random().toString(36).slice(2), LEASE=15000;
let slot=(()=>{try{return Math.max(0,Math.min(2,Number(localStorage.getItem('gem-shop-active')||0)))}catch(e){return 0}})(), state=null, page='town',modal=null,busy=false,readOnly=false,saveError='',audioContext=null,musicTimer=null;
const ui={sku:'R-AG',raw:null,lot:null,recipe:null,qty:1,style:'classic',name:'',direction:'horizontal',armed:false,tab:'active',bagTab:'raw',galleryTab:'materials',shape:0,rotation:0,recommend:0,classic:false,view:'overview',workGame:null,night:false,lowQuality:false};
function load(i){let v=localStorage.getItem(KEY+i);if(!v)return null;let s=JSON.parse(v);GemGame.validate(s);return s}
function leaseKey(){return KEY+slot+'-lease'}
function takeControl(force=false){try{let l=JSON.parse(localStorage.getItem(leaseKey())||'null');if(l&&l.owner!==OWNER&&Date.now()-l.time<LEASE&&!force){readOnly=true;return false}localStorage.setItem(leaseKey(),JSON.stringify({owner:OWNER,time:Date.now()}));readOnly=false;return true}catch(e){saveError='存档不可用';return false}}
function checkLease(){let l=JSON.parse(localStorage.getItem(leaseKey())||'null');if(l&&l.owner!==OWNER&&Date.now()-l.time<LEASE){readOnly=true;throw Error('另一个页面正在使用此存档。请先重新取得控制。')}takeControl()}
function release(){try{let l=JSON.parse(localStorage.getItem(leaseKey())||'null');if(l?.owner===OWNER)localStorage.removeItem(leaseKey())}catch(e){}}
window.addEventListener('pagehide',release);
setInterval(()=>{if(state&&!readOnly)try{checkLease()}catch(e){render()}},5000);
window.addEventListener('storage',e=>{if(e.key===KEY+slot||e.key===leaseKey()){let current=load(slot);if(current&&state&&current.revision!==state.revision){state=current;page=state.scene;modal=null;render();toast('存档已在另一页面更新，已载入最新进度')}try{let l=JSON.parse(localStorage.getItem(leaseKey())||'null');if(l?.owner!==OWNER){readOnly=true;render()}}catch(_){}}});
function toast(msg,error=false){let el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=msg;$('#toasts').append(el);setTimeout(()=>el.remove(),3800)}
function tone(kind='click'){if(!state?.settings.sound)return;try{audioContext||=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();let freqs=kind==='success'?[523,659,784]:kind==='error'?[196]:[440];freqs.forEach((f,i)=>{let o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+i*.09;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(.055,t);g.gain.exponentialRampToValueAtTime(.001,t+.19);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.2)})}catch(e){}}
function music(){clearInterval(musicTimer);musicTimer=null;if(!state?.settings.music)return;let step=0;musicTimer=setInterval(()=>{try{audioContext||=new (window.AudioContext||window.webkitAudioContext)();let o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime;o.frequency.value=[261.63,329.63,392,329.63,293.66,349.23,440,349.23][step++%8];g.gain.setValueAtTime(.018,t);g.gain.exponentialRampToValueAtTime(.001,t+1);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+1)}catch(e){}},900)}
async function commit(c){if(!state)throw Error('先开一家属于你的小店吧');if(busy)throw Error('正在保存，请稍等');busy=true;try{let perform=()=>{checkLease();let disk=load(slot);if(!disk||disk.id!==state.id||disk.revision!==state.revision){if(disk)state=disk;throw Error('存档已更新，请重新操作')}let next=GemGame.apply(state,c);try{localStorage.setItem(KEY+slot,JSON.stringify(next.state))}catch(err){saveError='保存失败';throw Error('保存失败，原有进度没有改变。请导出备份后检查浏览器存储。')}state=next.state;saveError='';return next.result};return navigator.locks?await navigator.locks.request(KEY+slot,perform):perform()}catch(e){if(e.name==='QuotaExceededError')saveError='保存失败：空间不足';throw e}finally{busy=false}}
async function run(c){try{return await commit(c)}catch(e){toast(e.message,true);tone('error');render();throw e}}
const B=(txt,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${txt}</button>`;
const nav=(p,label,icon,extra='')=>`<button class="navbtn ${page===p?'active':''} ${extra}" data-page="${p}" title="${label}">${I(icon)}<span>${label}</span>${p==='orders'&&state?.exercises.some(q=>q.slot==='Q3'&&!q.done)?'<i class="badge-dot"></i>':''}</button>`;
function nextStep(){if(!state)return{index:0,page:'town',text:'开一家小店'};let o=state.orders.find(o=>o.status==='active');if(!o)return{index:0,page:'orders',text:'看看新的顾客订单'};let r=CFG.recipes.find(r=>r.id===o.recipe);if(state.products.filter(p=>p.recipe===r.id&&p.status!=='sold').length>=o.qty)return{index:3,page:'sell',text:'去交付这份心意'};if(state.lots.some(l=>l.mat===r.mat&&l.groups*l.group>=r.use))return{index:2,page:'craft',text:'去加工你的作品'};if(state.raws.some(a=>a.mat===r.mat&&a.status==='raw'))return{index:1,page:'cut',text:'去切开原石看看'};return{index:0,page:'market',text:state.tutorialTrade?'去挑选合适的原石':'去挑选第一块原石'}}
function render(){document.body.classList.toggle('world-enabled',!ui.classic);document.body.classList.toggle('no-motion',state?.settings.motion===false);let sum=state?GemGame.summary(state):{count:0,profit:0};$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><button class="brand-mark" data-page="town" title="回到小镇">${I('gem')}</button>${nav('town','小镇','town')}${nav('orders','订单','orders')}${nav('bag','背包','bag')}${nav('ledger','账本','book')}${nav('gallery','图鉴','gem')}<div class="nav-divider"></div>${nav('decor','装饰','shop','extra-nav')}<div class="nav-spacer"></div>${nav('settings','设置','settings')}<button class="navbtn extra-nav" data-action="help">${I('help')}<span>怎么玩</span></button></aside><main class="main"><header class="topbar"><button class="logotype" data-page="town"><div><h2>宝石小掌柜</h2><small>THE LITTLE GEM SHOP</small></div></button><div class="top-actions"><span class="saved">${saveError||(!state?'等待开张':readOnly?'正在浏览':'进度已保存')}</span><div class="wallet" title="当前可用金币"><i class="coin">G</i><span id="coin-count">${state?.coins??1000}</span><small>金币</small></div><button class="profile" data-action="slots"><div class="avatar">${Art.person(state?.avatar||0)}</div><span>${E(state?.name||'小掌柜')} ${I('arrow','sm')}</span></button></div></header>${readOnly?'<div class="readonly">这个存档正在另一个页面使用。<button data-action="takeControl">在此页面继续</button></div>':''}${renderPage()}<footer class="footnote">慢慢来，把喜欢的石头，变成独一无二的作品。<span style="margin-left:15px">所有价格与材质线索仅用于本游戏</span></footer></main></div>`;renderModal();attachWorld();bindCut()}
function head(title,english,sub='',extra=''){return `<div class="page-head"><div class="scene-title"><div class="eyebrow">${english}</div><h1>${title}</h1>${sub?`<p class="sub">${sub}</p>`:''}</div>${extra}</div>`}
function sceneHead(title,english,sub){return head(title,english,sub,`<div><button class="back-btn" data-page="town">${I('back','sm')}回到小镇</button><div class="scene-nav">${[['market','采购'],['cut','切割'],['craft','加工'],['sell','售卖']].map(([p,n])=>`<button class="${page===p?'active':''}" data-page="${p}">${n}</button>`).join('')}</div></div>`)}
function renderPage(){if(!state&&page!=='town')page='town';return decorate3D(page,({town:town,market:market,cut:cut,craft:craft,sell:sell,orders:orders,bag:bag,ledger:ledger,gallery:gallery,decor:decor,settings:settings})[page]())}
function town(){let n=nextStep(),s=state;let labels=[['market','原石集市','挑选一份惊喜',34.2,47.65],['cut','切割工坊','发现石头的秘密',67.9,43.5],['craft','手作工坊','让想象变成作品',33.8,77.3],['sell','宝石小铺','把心意交到手中',71.7,80.3]];return head(s?(s.tutorialTrade?'新的一天，继续创造。':'小掌柜，欢迎开张。'):'每一块石头，都有惊喜。','A LITTLE TOWN, A BIG DREAM',s?'挑选、发现、制作，再把美好送到顾客手中。':'经营你的宝石小铺，在创造中发现算术的乐趣。',`<span class="pill">${I('leaf','sm')}自由经营 · 不用赶时间</span>`)+`<div class="town-grid"><div><div class="map-card"><img src="town.svg" alt="宝石小镇：原石集市、切割工坊、手作工坊和宝石小铺，围绕中央广场分布"><div class="map-title">GEMSTONE VILLAGE</div><div class="map-weather">${I('sun','sm')}晴 · 适合创造</div>${labels.map(([p,a,b,x,y],i)=>`<button style="left:${x}%;top:${y}%" class="map-label ${n.page===p?'suggest':''}" data-page="${p}"><b>0${i+1}</b><div>${a}<span>${b}</span></div></button>`).join('')}${s?.applied.includes('D-01')?`<div class="decoration-sign">${E(s.name)}的宝石铺</div>`:''}${s?.applied.includes('D-02')?'<div class="shelf-mark"></div>':''}${s?.applied.includes('D-03')?'<div class="decoration-light"></div>':''}<div class="map-caption">点击一间小屋，开始今天的故事</div></div><div class="town-footer"><button class="small-card" data-page="gallery"><div class="tiny-art">${I('gem')}</div><div><h3>我的宝石图鉴</h3><p>已发现 ${s?.discovered.length||0} / 4 种材料</p></div><span class="arrow">↗</span></button><button class="small-card" data-page="ledger"><div class="tiny-art">${I('book')}</div><div><h3>小小经营家</h3><p>已完成 ${s?GemGame.summary(s).count:0} 笔生意</p></div><span class="arrow">↗</span></button><button class="small-card" data-page="decor"><div class="tiny-art">${I('shop')}</div><div><h3>装扮我的小铺</h3><p>让喜欢的风格住进来</p></div><span class="arrow">↗</span></button></div></div><div class="aside">${questCard()}<div class="hint-card">${I('spark')}<div><h4>${s?.coins<180?'有点周转不开？':'小掌柜的灵感笔记'}</h4><p>${s?.coins<180?'顾客会准备好材料，免费帮工一次可获得 80 金币。':'收入减去成本，才是赚到的金币。试着把每笔小生意记在心里。'}</p>${s?.coins<180?'<button class="text-btn" data-action="support">去帮帮忙 →</button>':''}</div></div></div></div>`}
function questCard(){let o=state?.orders.find(o=>o.status==='active')||{...CFG.orders[0],price:210},r=CFG.recipes.find(r=>r.id===o.recipe),n=nextStep();return `<section class="quest-card"><div class="section-top"><h3>${I('orders','sm')}今日的小心愿</h3><span class="small-tag">${state?.tutorialTrade?'顾客订单':'开张第一单'}</span></div><div class="customer"><div class="avatar">${Art.person(CFG.orders.findIndex(t=>t.recipe===o.recipe)%4)}</div><div><strong>${E(o.who)}</strong><small>来自小镇的一份期待</small></div></div><div class="speech">“${E(o.story)}”</div><div class="order-product"><div class="product-mini">${G(r.mat,r.kind)}</div><div><h3>${E(r.name)} × ${o.qty}</h3><p>用一份认真，做一份礼物</p></div></div><div class="reward"><span>完成后可收到</span><strong><i class="coin">G</i>${o.price*o.qty}<small>金币</small></strong></div><div class="quest-steps" ${state?.settings.guidance===false?'hidden style="display:none"':''}>${['采购','切割','加工','售卖'].map((x,i)=>`<div class="quest-step ${i<n.index?'done':i===n.index?'current':''}"><i>${i<n.index?'✓':i+1}</i>${x}</div>`).join('')}</div>${B(n.text+I('arrow','sm'),state?'next':'start','full')}<button class="text-btn" data-page="orders" style="width:100%;justify-content:center">查看订单板 ${I('arrow','sm')}</button>${state?.exercises.some(q=>q.slot==='Q3'&&!q.done)?B('看懂上次的账单','pendingMath','ghost full small'):''}</section>`}
function market(){let r=CFG.raws.find(x=>x.id===ui.sku)||CFG.raws[0],rs=CFG.recipes.filter(p=>p.mat===r.mat);if(!rs.some(p=>p.id===ui.recipe))ui.recipe=rs[0].id;let p=rs.find(p=>p.id===ui.recipe),d=state.drafts['buy:'+r.id],qty=d?.recipe===p.id?d.qty:Math.floor(r.qty/p.use),total=r.price+r.cut+p.fee*qty;return sceneHead('从一块原石开始。','01 / THE STONE MARKET','仔细观察纹路，选一块适合你的石头。')+`<div class="workspace"><section><div class="panel-title"><h3>今日的原石</h3><small>固定供应 · 每次购买一块</small></div><div class="market-grid">${CFG.raws.map((a,i)=>`<button class="stone-card ${r.id===a.id?'selected':''} ${!state.tutorialTrade&&i>0?'locked':''}" data-action="selectSku" data-id="${a.id}"><span class="corner">${['练手摊位','练手摊位','雕刻摊位','首饰摊位'][i]}</span>${G(a.mat,'raw','classic',i%2)}<h3>${a.name}</h3><div class="stone-meta"><span>切后 ${a.qty} 份 · ${a.shape.split(' / ')[0]}</span><strong class="price">${a.price} <small>金币</small></strong></div>${!state.tutorialTrade&&i>0?'<p class="fine">第一笔生意完成后开放</p>':''}</button>`).join('')}</div><p class="fine" style="padding:8px">材料颜色、线索和价格是游戏设定。免费观察，不会消耗金币。</p></section><aside class="panel"><div class="observe"><div style="width:190px;transform:rotate(${ui.rotation}deg)">${G(r.mat,'raw','classic',ui.shape)}</div><button class="rotate-btn" data-action="rotate" title="旋转观察">${I('rotate','sm')}</button></div><h3>${E(r.name)}</h3><div class="chip-row"><button class="chip ${ui.shape===0?'active':''}" data-action="shape" data-value="0">${r.shape.split(' / ')[0]}</button><button class="chip ${ui.shape===1?'active':''}" data-action="shape" data-value="1">${r.shape.split(' / ')[1]}</button></div><div class="clue">观察线索：${r.clue}${!state.tutorialTrade?'<br>这块原石可以完成小桃的玛瑙订单。':''}</div><div class="field"><label for="buy-recipe">计划制作</label><select id="buy-recipe">${rs.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${E(x.name)} × ${Math.floor(r.qty/x.use)}</option>`).join('')}</select></div><div class="calc"><div><span>本次原石</span><span>${r.price} 金币</span></div><div><span>后续切割</span><span>${r.cut} 金币</span></div><div><span>计划加工 ${qty} 件</span><span>${p.fee*qty} 金币</span></div><div class="total"><span>完整计划预算</span><strong>${total} <small>金币</small></strong></div></div>${state.coins<total?`<p class="notice">完成全部步骤还差 ${total-state.coins} 金币。可先选晶光原石的 180 金币路线，或免费帮工。</p>`:''}${B('挑好了，算算预算 '+I('arrow','sm'),'buyPrepare','full',state.coins<r.price?'disabled':'')}<p class="fine">现在只需支付 ${r.price} 金币。切割和加工到下一步再付。</p>${state.coins<r.price?B('帮工赚启动金','support','secondary full'):''}</aside></div>`}
function cut(){let raws=state.raws.filter(r=>r.status==='raw');if(!raws.some(r=>r.id===ui.raw))ui.raw=raws[0]?.id;let r=raws.find(r=>r.id===ui.raw);return sceneHead('打开石头里的秘密。','02 / THE CUTTING WORKSHOP','跟随引导轻轻划过，发现里面藏着的宝石。')+(r?`<div class="workspace"><section><div class="chip-row">${raws.map((r,i)=>`<button class="chip ${r.id===ui.raw?'active':''}" data-action="selectRaw" data-id="${r.id}">${E(r.name)} · 第 ${i+1} 块</button>`).join('')}</div><div class="workbench" id="cut-bench"><div class="bench-label">CUTTING TABLE / 安全的想象工坊</div><div class="main-gem">${G(r.mat,'raw','classic',r.seed)}</div><svg class="cut-guide" id="cut-guide" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="沿虚线从一端划到另一端"><line x1="25" y1="${ui.direction==='horizontal'?50:70}" x2="75" y2="${ui.direction==='horizontal'?50:30}"/><circle cx="25" cy="${ui.direction==='horizontal'?50:70}" r="2"/><circle cx="75" cy="${ui.direction==='horizontal'?50:30}" r="2"/><path id="cut-trail" stroke="#eab17a" stroke-width="1.4" fill="none"/></svg><span class="cut-status">${ui.armed?'沿虚线从一端划到另一端':'先确认费用，再开始切割'}</span></div><p class="fine">鼠标和手指都可以划线。划偏可重试，不会扣钱或损坏原石。</p></section><aside class="panel"><h3>这次的发现</h3><div class="field"><label>原石</label><p>${E(r.name)} · ${r.qty} 份材料</p></div><div class="field"><label>选择切割方向</label><div class="style-options"><button class="chip ${ui.direction==='horizontal'?'active':''}" data-action="direction" data-value="horizontal">水平切开</button><button class="chip ${ui.direction==='diagonal'?'active':''}" data-action="direction" data-value="diagonal">斜向切开</button></div></div><div class="clue">${r.clue}<br>切割方向不会改变材质或产量。</div><div class="calc"><div><span>切割费</span><strong>${r.cut} 金币</strong></div><div><span>完成后钱包</span><span>${state.coins-r.cut} 金币</span></div></div>${state.coins<r.cut?`<p class="notice">还差 ${r.cut-state.coins} 金币</p>${B('帮工赚启动金','support','secondary full')}`:ui.armed?`${B('辅助完成切割','assistCut','full')}${B('取消，暂时不切','unarm','ghost full','style="margin-top:10px"')}`:B('确认费用，开始划线','armCut','full')}<p class="fine">只有有效划线完成后，才会扣除切割费。辅助切割的结果完全一样。</p></aside></div>`:`<section class="panel"><div class="empty">${I('scissors')}<h3>工作台等你带来一块原石</h3><p>已经切开的材料，在背包里等你制作。先去集市看看吧。</p><div class="actions">${B('去原石集市','gotoMarket')} ${B('去加工材料','gotoCraft','secondary')}</div></div>${state.raws.some(r=>r.status==='cut')?'<button class="text-btn" data-action="cutHistory">查看已经切出的材料 →</button>':''}</section>`)}
function craft(){let lots=state.lots.filter(l=>l.groups>0);if(!lots.some(l=>l.id===ui.lot))ui.lot=lots[0]?.id;let l=lots.find(l=>l.id===ui.lot);if(!l)return sceneHead('把想象，变成作品。','03 / THE CRAFT STUDIO','选择材料、款式与外观，做一份有心意的礼物。')+`<section class="panel"><div class="empty">${I('hammer')}<h3>好作品，从好材料开始</h3><p>先切开一块原石，再回来挑选你喜欢的配方。</p>${B('去切割工坊','gotoCut')}</div></section>`;let rs=CFG.recipes.filter(p=>p.mat===l.mat);if(!rs.some(r=>r.id===ui.recipe))ui.recipe=rs[0].id;let r=rs.find(r=>r.id===ui.recipe),max=Math.floor(l.groups*l.group/r.use);ui.qty=Math.min(Math.max(1,ui.qty),Math.max(1,max));let styleOptions=r.kind==='animal'?[['classic','小猫'],['bunny','小兔']]:r.kind==='pendant'?[['classic','水滴'],['star','星星']]:[['classic','经典款']];if(!styleOptions.some(x=>x[0]===ui.style))ui.style='classic';return sceneHead('把想象，变成作品。','03 / THE CRAFT STUDIO','每一种材料，都有属于它的好主意。')+`<div class="workspace"><section><div class="field" style="margin:0 0 16px"><label for="craft-lot">材料批次（每次制作只用同一批材料）</label><select id="craft-lot">${lots.map((x,i)=>`<option value="${x.id}" ${x.id===l.id?'selected':''}>${CFG.materials[x.mat].name} · 批次 ${x.raw} · 余 ${x.groups*x.group} 份</option>`).join('')}</select></div><div class="workbench crafting"><span class="bench-label">HANDMADE WITH A LITTLE LOVE</span><div class="main-gem">${G(r.mat,r.kind,ui.style)}</div><span class="bench-props">成品预览 · 换外观不收费</span></div><div class="chip-row">${rs.map(x=>`<button class="chip ${x.id===r.id?'active':''}" data-action="selectRecipe" data-id="${x.id}">${E(x.name)}</button>`).join('')}</div></section><aside class="panel"><h3>${E(r.name)}</h3><p class="sub">每件用 ${r.use} 份${CFG.materials[l.mat].name}</p><div class="field"><label>选择外观</label><div class="style-options">${styleOptions.map(([v,n])=>`<button class="chip ${v===ui.style?'active':''}" data-action="style" data-value="${v}">${n}</button>`).join('')}</div></div><div class="field"><label for="craft-name">给作品起个名字（可选，最多 12 字）</label><input id="craft-name" maxlength="12" value="${E(ui.name)}" placeholder="${E(r.name)}"></div><div class="field"><label for="craft-qty">制作数量</label><input id="craft-qty" type="number" min="1" max="${Math.max(1,max)}" value="${ui.qty}"></div><div class="calc"><div><span>材料用量</span><span>${r.use*ui.qty} / ${l.groups*l.group} 份</span></div><div><span>制作后剩余</span><span>${l.groups*l.group-r.use*ui.qty} 份</span></div><div><span>每件加工费</span><span>${r.fee} 金币</span></div><div class="total"><span>本次加工费</span><strong>${r.fee*ui.qty} <small>金币</small></strong></div></div>${max<1?`<p class="notice">此批还缺 ${r.use-l.groups*l.group} 份材料。可换另一款配方或批次。</p>`:state.coins<r.fee*ui.qty?`<p class="notice">加工费还差 ${r.fee*ui.qty-state.coins} 金币</p>`:''}${B('制作 '+ui.qty+' 件作品 '+I('spark','sm'),'craftPrepare','full',max<1||state.coins<r.fee*ui.qty?'disabled':'')}${state.coins<180?'<button class="text-btn" data-action="support">帮工赚启动金 →</button>':''}<p class="fine">加工费已包含挂绳、底座等配件，无额外费用。</p></aside></div>`}
function orderCard(o,isTemplate=false){let r=CFG.recipes.find(r=>r.id===o.recipe),t=CFG.orders.find(t=>t.recipe===o.recipe),qty=o.qty,price=o.price??r.price,owned=state.products.filter(p=>p.recipe===r.id&&p.status!=='sold').length,active=state.orders.some(a=>a.template===t.id&&a.status==='active'),idx=CFG.orders.indexOf(t);return `<article class="order-card"><div class="customer"><div class="avatar">${Art.person(idx%4)}</div><div><strong>${E(o.who||t.who)}</strong><small>${o.tutorial?'开张第一单':isTemplate?'等待接单':o.status==='done'?'已送出心意':'正在期待你的作品'}</small></div></div><h3>${E(o.name)}</h3><div class="speech">${E(o.story||t.story)}</div><div class="order-product"><div class="product-mini">${G(r.mat,r.kind)}</div><div><h3>${E(r.name)}</h3><p>${qty} 件 · 每件 ${price} 金币</p><p>背包里有 ${owned} 件</p></div></div><div class="reward"><span>整单收入</span><strong>${qty*price}<small>金币</small></strong></div><div class="order-actions">${isTemplate?B(active?'正在制作':'接下这个心愿','accept','full small',`data-id="${t.id}" ${active||!state.tutorialTrade?'disabled':''}`):o.status==='done'?'<span class="pill">已完成，谢谢你的认真</span>':`${B(owned>=qty?'准备交付':'去准备作品',owned>=qty?'sellPrepare':'forOrder','small',`data-id="${o.id}"`)}${!o.tutorial?`<button class="text-btn" data-action="cancelOrder" data-id="${o.id}">取消</button>`:''}`}</div>${!isTemplate&&o.status==='active'&&owned<qty?`<p class="fine">还需要 ${qty-owned} 件，整单备齐后交付。</p>`:''}</article>`}
function sell(){let active=state.orders.filter(o=>o.status==='active');return sceneHead('把美好，送到手中。','04 / THE LITTLE GEM SHOP','整单交付，让每一份心意都有着落。')+`<div class="orders-grid">${active.map(o=>orderCard(o)).join('')||`<div class="panel empty">${I('shop')}<h3>小铺准备好迎接新朋友了</h3>${B('看看新的订单','gotoOrders')}</div>`}</div>`}
function orders(){let recommendations=[CFG.orders[2],...CFG.orders.filter(o=>o.id!=='O-003').filter((o,i)=>[ui.recommend,(ui.recommend+1)%7].includes(i))];let pending=state.exercises.filter(q=>q.slot==='Q3'&&!q.done);return head('每一份期待，都值得用心。','THE WISH BOARD','订单没有截止时间，按照自己的节奏慢慢完成。',`<span class="pill">进行中 ${state.orders.filter(o=>o.status==='active').length} / 3</span>`)+`${state.tutorialTrade&&ui.tab==='active'?`<div class="panel-title"><h3>小镇推荐</h3><button class="text-btn" data-action="refreshRecommendations">换一组心愿 ↻</button></div><div class="chip-row">${recommendations.map(o=>`<button class="chip" data-action="accept" data-id="${o.id}">${o.id==='O-003'?'180 金币低成本路线 · ':''}${o.name}</button>`).join('')}</div>`:''}${pending.length?`<div class="clue">你有 ${pending.length} 张已成交的账单还没看懂。 <button class="text-btn" data-action="pendingMath">继续小算术 →</button></div>`:''}<div class="tabs">${[['active','正在制作'],['all','全部心愿 · 8'],['done','已经送达']].map(([v,n])=>`<button class="${ui.tab===v?'active':''}" data-action="orderTab" data-value="${v}">${n}</button>`).join('')}</div><div class="orders-grid">${ui.tab==='all'?CFG.orders.map(o=>orderCard(o,true)).join(''):state.orders.filter(o=>o.status===(ui.tab==='done'?'done':'active')).map(o=>orderCard(o)).join('')||'<div class="empty"><h3>这里还没有订单</h3><p>打开“全部心愿”，找一份想完成的礼物。</p></div>'}</div>`}
function bag(){let raws=state.raws.filter(r=>r.status==='raw'),lots=state.lots.filter(l=>l.groups),products=state.products.filter(p=>p.status!=='sold'),arr=ui.bagTab==='raw'?raws:ui.bagTab==='material'?lots:products;return head('你的宝物，都在这里。','MY LITTLE BACKPACK','原石、材料和成品分开收好，每一批都有来处。')+`<div class="tabs">${[['raw','原石',raws.length],['material','材料',lots.length],['product','成品',products.length]].map(([v,n,c])=>`<button class="${ui.bagTab===v?'active':''}" data-action="bagTab" data-value="${v}">${n} · ${c}</button>`).join('')}</div><div class="inventory-grid">${arr.map(x=>ui.bagTab==='raw'?`<article class="item-card"><div class="item-art">${G(x.mat,'raw','classic',x.seed)}</div><h3>${E(x.name)}</h3><p>购买成本 ${x.price} 金币</p><p>批次 ${E(x.id)}</p>${B('去切开','bagCut','small secondary',`data-id="${x.id}"`)}</article>`:ui.bagTab==='material'?`<article class="item-card"><div class="item-art">${G(x.mat,'material')}</div><h3>${CFG.materials[x.mat].name} · ${x.groups*x.group} 份</h3><p>库存成本 ${x.groups*x.groupCost} 金币</p><p>来源 ${E(x.raw)}</p>${B('去制作','bagCraft','small secondary',`data-id="${x.id}"`)}</article>`:`<article class="item-card"><div class="item-art">${G(x.mat,x.kind,x.style)}</div><h3>${E(x.name)}</h3><p>${CFG.recipes.find(r=>r.id===x.recipe).name}</p><p>成本 ${x.cost} 金币 · ${E(x.raw)}</p><div class="row">${B(state.collection.some(y=>y.id===x.id)?'已留影':'留影收藏','collect','small secondary',`data-id="${x.id}"`)}<button class="text-btn" data-action="rename" data-id="${x.id}">改名</button></div></article>`).join('')}</div>${arr.length?'':`<div class="empty">${I('bag')}<h3>背包还是空的，去探索吧</h3><p>下一份惊喜，就藏在集市的小石头里。</p>${B('回到小镇','gotoTown')}</div>`}`}
function ledger(){let sum=GemGame.summary(state),qs=state.exercises.filter(q=>q.committed&&(q.attempts||q.mode==='demo')),first=qs.filter(q=>q.firstCorrect).length;return head('每一笔小生意，都算清楚。','THE SHOP LEDGER','收入是收进来的钱；利润，是收入减去商品成本。')+`<div class="stat-grid">${[['商品销售收入',sum.revenue],['商品销售利润',sum.profit],['库存成本',sum.stock],['免费帮工收入',sum.help]].map(([n,v],i)=>`<div class="stat ${i===1?'positive':''}"><span>${n} · 金币</span><strong>${v}</strong></div>`).join('')}</div><div class="panel"><div class="panel-title"><h3>金币流水</h3><small>装饰支出 ${sum.decor} · 已完成 ${sum.count} 单</small></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>这次做了什么</th><th>金币变化</th><th>商品成本</th><th>销售利润</th><th>来源</th></tr></thead><tbody>${state.transactions.slice().reverse().map(t=>`<tr><td>${new Date(t.time).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</td><td>${E(t.label)}</td><td class="${t.delta>=0?'positive-text':'negative-text'}"><strong>${t.delta>=0?'+':''}${t.delta}</strong></td><td>${t.cost??'—'}</td><td>${t.profit??'—'}</td><td>${E(t.raw||t.order||'小铺')}</td></tr>`).join('')||'<tr><td colspan="6">开张礼物：1000 金币。第一笔生意，等你来记录。</td></tr>'}</tbody></table></div></div><div class="hint-card">${I('leaf')}<div><h4>学习也在悄悄成长</h4><p>首次独立答对 ${first} / ${qs.length} 道已提交交易的算术题。提示和演示都能帮助你进步，不影响正常经营。</p></div></div>`}
function gallery(){let names=['第一笔生意','预算小能手','材料规划师'],badges=GemGame.badges(state);return head('收藏每一次小小的发现。','THE GEM COLLECTION','材料与款式会一直点亮，卖出作品也不会失去回忆。')+`<div class="tabs">${[['materials','材料 · '+state.discovered.length+'/4'],['recipes','款式 · '+state.recipes.length+'/8'],['photos','作品柜 · '+state.collection.length],['badges','成长徽章']].map(([v,n])=>`<button class="${ui.galleryTab===v?'active':''}" data-action="galleryTab" data-value="${v}">${n}</button>`).join('')}</div>${ui.galleryTab==='badges'?`<div class="deco-grid">${names.map((n,i)=>`<article class="panel ${badges[i]?'':'locked'}"><div class="deco-art" style="opacity:${badges[i]?1:.3};color:#b79b53">${I(['shop','book','hammer'][i])}</div><h3>${n}</h3><p class="sub">${['完成第一张教程订单','3 次采购预算首次独立答对','3 个批次的材料题首次独立答对'][i]}</p><p class="notice">${badges[i]?'已经获得':'继续慢慢成长'}</p></article>`).join('')}</div>`:`<div class="inventory-grid">${ui.galleryTab==='materials'?Object.entries(CFG.materials).map(([id,m])=>`<article class="item-card ${state.discovered.includes(id)?'':'locked'}"><div class="item-art">${G(id,'material')}</div><h3>${state.discovered.includes(id)?m.name:'尚未发现'}</h3><p>${state.discovered.includes(id)?m.desc:'在切割工坊，发现这份惊喜。'}</p></article>`).join(''):ui.galleryTab==='recipes'?CFG.recipes.map(r=>`<article class="item-card ${state.recipes.includes(r.id)?'':'locked'}"><div class="item-art">${G(r.mat,r.kind)}</div><h3>${E(r.name)}</h3><p>${state.recipes.includes(r.id)?'你已经学会制作这份礼物。':'亲手制作一次，即可点亮。'}</p><p>${r.use} 份材料 · ${r.fee} 金币加工费</p></article>`).join(''):state.collection.map(p=>`<article class="item-card"><div class="item-art">${G(p.mat,p.kind,p.style)}</div><h3>${E(p.name)}</h3><p>作品留影 · ${CFG.materials[p.mat].name}</p><p>照片不会占用实体库存</p></article>`).join('')||'<div class="empty"><h3>把喜欢的作品留个影吧</h3><p>在背包中点击“留影收藏”，回忆会一直留在这里。</p></div>'}</div>`}`}
function decor(){let sum=GemGame.summary(state);return head('让小铺，有你的模样。','MAKE IT YOUR OWN','装饰只改变外观，购买一次就永久拥有。')+`<div class="deco-grid">${CFG.decos.map((d,i)=>{let owned=state.owned.includes(d.id),applied=state.applied.includes(d.id),can=i===0?state.tutorialTrade:i===1?sum.count>=3:state.recipes.length>=4;return `<article class="panel"><div class="deco-art">${Art.decor(d.id)}</div><h3>${d.name}</h3><p class="sub">${d.rule}</p><div class="calc"><div><span>${owned?'已经拥有':'购买价格'}</span><strong>${owned?'免费切换':d.price+' 金币'}</strong></div></div>${B(owned?(applied?'暂时收起':'布置到小镇'):can?'预览并购买':'还没有解锁','decorPrepare','full '+(owned?'secondary':''),`data-id="${d.id}" ${!can?'disabled':''}`)}</article>`}).join('')}</div>`}
function settings(){return head('舒服地玩，安心地保存。','SETTINGS & SAVES','三个独立的小铺，每一个都有自己的故事。')+`<div class="settings-grid"><section class="panel"><h3>游戏偏好</h3><div class="setting-row"><div>算术难度<small>下一道新题生效，商品价格不变。</small></div><select id="difficulty">${['入门','标准','挑战'].map(v=>`<option ${state.settings.difficulty===v?'selected':''}>${v}</option>`).join('')}</select></div>${[['sound','操作音效','轻轻的按钮与成交提示音'],['music','背景音乐','慢节奏的原创合成音旋律'],['motion','轻量动效','切割、打磨和庆祝动效'],['guidance','新手引导','显示下一步操作建议']].map(([k,n,d])=>`<div class="setting-row"><div>${n}<small>${d}</small></div><button class="toggle ${state.settings[k]?'on':''}" data-action="toggleSetting" data-key="${k}" aria-label="${n}" aria-pressed="${state.settings[k]}"><i></i></button></div>`).join('')}<button class="text-btn" data-action="help">查看玩法说明 →</button></section><section class="panel"><h3>我的小铺存档</h3>${slotCards()}<div class="actions" style="display:flex;gap:10px;margin-top:18px">${B(I('download','sm')+'备份存档','export','secondary')}${B(I('upload','sm')+'恢复备份','import','ghost')}</div><p class="fine">进度保存在当前浏览器。清理浏览器、更换设备或切换在线/离线版本前，请先导出 JSON 备份。恢复前可以选择存档位置。</p><div class="clue">离线版不依赖网络，昵称和学习记录不上传。每次交易成功后自动保存。</div></section></div>`}
function slotCards(){return [0,1,2].map(i=>{let x=null,bad=false;try{x=load(i)}catch(e){bad=true}return `<button class="save-slot ${slot===i&&state?'current':''}" data-action="selectSlot" data-index="${i}"><div class="avatar">${Art.person(x?.avatar??i)}</div><div class="slot-info"><strong>${E(x?.name|| (bad?'存档损坏，请从备份恢复':'开一家新的小店'))}</strong><small>存档 ${i+1}${x?' · '+new Date(x.updated).toLocaleDateString('zh-CN')+(slot===i?' · 当前小铺':''):''}</small></div><b>${x?x.coins+' G':'＋'}</b></button>`}).join('')}
function openModal(m){modal=m;renderModal()}
function closeModal(){modal=null;renderModal()}
function renderModal(){let html='';if(modal){switch(modal.type){case 'start':html=`<div class="welcome-graphic"><img src="town.svg" alt="宝石小镇"></div><div class="eyebrow">YOUR STORY BEGINS HERE</div><h2>开一家属于你的小店。</h2><p>1000 金币、一块原石，还有好多等待实现的小心愿。准备好了吗？</p><div class="field"><label for="nickname">小掌柜的名字</label><input id="nickname" maxlength="12" placeholder="小掌柜" value=""></div><div class="field"><label>挑一个喜欢的头像</label><div class="style-options">${[0,1,2,3].map(i=>`<button class="chip ${modal.avatar===i?'active':''}" data-action="avatar" data-index="${i}" aria-label="头像 ${i+1}"><span class="avatar" style="display:block">${Art.person(i)}</span></button>`).join('')}</div></div><div class="actions">${B('跟着做，开张啦 '+I('arrow','sm'),'createSave')}${B('自己试试','createSolo','ghost')}</div><p class="fine">存档 ${modal.slot+1} · 不需要真实姓名 · 没有倒计时</p>`;break;
case 'slots':html=`<h2>选择你的宝石小铺</h2><p>三个存档独立保存金币、订单与作品。</p>${slotCards()}${B('从备份恢复','import','ghost full')}`;break;
case 'math':{let q=state.exercises.find(q=>q.id===modal.id);if(!q){closeModal();return}html=`<div class="math-top"><div class="math-mark">＋</div><div><span class="eyebrow" style="margin-bottom:4px">A LITTLE MATH MOMENT</span><span class="math-scope">${E(q.snapshot.scope)} · ${E(q.snapshot.difficulty)} · ${q.slot==='Q3'?'货款已经到账':'此时还没有扣款'}</span></div></div><h2>${E(q.snapshot.title)}</h2><div class="math-details">${E(q.snapshot.detail)}</div>${q.done?`<div class="math-success"><strong>${q.mode==='demo'?'看懂了，也是一种进步。':'算对啦！'}</strong><p>${E(q.snapshot.formula)} = ${q.snapshot.answer} ${E(q.snapshot.unit)}</p></div><div class="actions">${B(q.slot==='Q3'?'收好这张账单':'继续确认方案 '+I('arrow','sm'),'mathContinue','full')}</div>`:`<div class="answer-row"><input id="math-answer" inputmode="numeric" autocomplete="off" maxlength="9" aria-label="填写答案" placeholder="?" value="${E(modal.input||'')}"><span>${E(q.snapshot.unit)}</span></div><div class="numpad">${['1','2','3','4','5','6','7','8','9','清空','0','⌫'].map(v=>`<button data-action="digit" data-value="${v}">${v}</button>`).join('')}</div>${q.hint?`<div class="math-hint"><strong>提示 ${q.hint} / 3</strong><br>${E(q.hint===1?q.snapshot.hint:q.hint===2?'可以这样列式：'+q.snapshot.formula:q.snapshot.formula+' = '+q.snapshot.answer+' '+q.snapshot.unit+'。把每个数字和题目里的条件对应起来看看。')}</div>`:''}${modal.feedback?`<p class="math-feedback">${modal.feedback}</p>`:''}<div class="actions">${q.hint===3?B('我明白了，继续','mathDemo'):B('检查答案','mathSubmit')}${B('给我一点提示','mathHint','ghost')}</div><p class="fine">算错不扣金币，也不会丢失材料。${q.slot==='Q3'?'可以暂时关闭，稍后从订单板继续。':''}</p>`}`;break}
case 'buyConfirm':{let d=state.drafts['buy:'+modal.sku],r=CFG.raws.find(r=>r.id===modal.sku);html=`<div class="result-art">${G(r.mat,'raw','classic',ui.shape)}</div><h2>就选这块${E(r.name)}。</h2><div class="receipt"><div><span>现在支付</span><strong>${r.price} 金币</strong></div><div><span>购买后钱包</span><strong>${state.coins-r.price} 金币</strong></div><div><span>后续还需预留</span><strong>${d.cost-r.price} 金币</strong></div></div>${state.coins<d.cost?`<p class="notice">完整计划还差 ${d.cost-state.coins} 金币。可以换低价原石，或购买后免费帮工。</p>`:''}<div class="actions">${B('确认购买','buyConfirm')}${B('再看看','close','ghost')}</div>`;break}
case 'cutResult':html=`<div class="eyebrow">A NEW DISCOVERY</div><div class="result-art">${G(modal.mat,'material')}</div><h2>是${CFG.materials[modal.mat].name}！</h2><p>得到了 ${modal.qty} 份材料。${CFG.materials[modal.mat].desc}</p><div class="actions">${B('去制作一份礼物 '+I('arrow','sm'),'gotoCraft')}${B('先收好','close','ghost')}</div>`;break;
case 'craftConfirm':{let d=state.drafts['craft:'+modal.lot],r=CFG.recipes.find(r=>r.id===d.recipe),l=state.lots.find(l=>l.id===d.lot);html=`<div class="result-art">${G(r.mat,r.kind,d.style)}</div><h2>准备制作 ${d.qty} 件作品</h2><div class="receipt"><div><span>用掉材料</span><strong>${r.use*d.qty} 份${CFG.materials[l.mat].name}</strong></div><div><span>加工费</span><strong>${r.fee*d.qty} 金币</strong></div><div><span>剩余材料</span><strong>${l.groups*l.group-r.use*d.qty} 份</strong></div></div><div class="actions">${B('确认，开始制作','craftConfirm')}${B('再调整一下','close','ghost')}</div>`;break}
case 'craftResult':{let r=CFG.recipes.find(r=>r.id===modal.recipe);html=`<div class="eyebrow">MADE BY YOU</div><div class="result-art">${G(r.mat,r.kind,modal.style)}</div><h2>你的作品，完成啦。</h2><p>${modal.qty} 件${E(r.name)}已放入背包。可以留一张作品照片，再送给期待它的顾客。</p><div class="actions">${B('去小铺交付 '+I('arrow','sm'),'gotoSell')}${B('留影收藏','collectResult','ghost')}</div>`;break}
case 'sellConfirm':{let o=state.orders.find(o=>o.id===modal.order),ps=state.products.filter(p=>p.recipe===o.recipe&&p.status!=='sold'),picked=ps.filter(p=>modal.items.includes(p.id)),cost=picked.reduce((a,p)=>a+p.cost,0);html=`<h2>把这份心意交给${E(o.who)}</h2><p>请选择 ${o.qty} 件成品，整单一起交付。已默认选择最早制作的作品。</p><div style="max-height:240px;overflow:auto">${ps.map(p=>`<label class="product-choice"><input type="checkbox" data-item="${p.id}" ${modal.items.includes(p.id)?'checked':''}>${G(p.mat,p.kind,p.style)}<span>${E(p.name)}<small>来源 ${p.raw} · 成本 ${p.cost} 金币</small></span></label>`).join('')}</div><div class="receipt"><div><span>本单收入</span><strong>${o.qty*o.price} 金币</strong></div><div><span>选中商品成本</span><strong>${cost} 金币</strong></div><div class="big"><span>本单利润</span><strong>${o.qty*o.price-cost} 金币</strong></div></div><div class="actions">${B('确认交付 '+o.qty+' 件','sellConfirm','',modal.items.length!==o.qty?'disabled':'')}${B('再等等','close','ghost')}</div>`;break}
case 'receipt':html=`<div class="eyebrow">THANK YOU FOR YOUR CRAFT</div><div class="hero-icon">${Art.person(modal.customer||0)}</div><h2>一份心意，顺利送达。</h2><p>“做得真漂亮，谢谢你，小掌柜！”</p><div class="receipt"><div><span>本单销售收入</span><strong>${modal.revenue} 金币</strong></div><div><span>本单商品成本</span><strong>${modal.cost} 金币</strong></div><div class="big"><span>本单销售利润</span><strong>${modal.profit} 金币</strong></div><div><span>现在的钱包</span><strong>${state.coins} 金币</strong></div></div>${modal.remaining?'<p class="fine">本批还有库存，剩余物品成本保留在背包中。</p>':''}<div class="actions">${B(modal.q?'看懂这张账单':'接待下一位顾客',modal.q?'receiptMath':'gotoOrders')}${B('先回小镇','gotoTown','ghost')}</div>`;break;
case 'support':{let h=state.support;html=`<div class="eyebrow">A HELPING HAND</div><div class="hero-icon">${Art.person(3)}</div><h2>帮奶奶串两条手链</h2><p>奶奶准备了 12 颗珠子，每条手链用 6 颗。材料和费用都由奶奶提供，完成后获得 80 金币。</p><div class="clue">委托材料放在专用工作台，不占用你的背包。</div>${h?.status==='active'?`<div class="actions">${B(h.stage===0?'动手串好手链':'算好数量，交付委托',h.stage===0?'makeSupport':'supportMath')}${B('取消委托','cancelSupport','ghost')}</div>`:`<div class="actions">${B('接受免费委托','startSupport','',state.coins>=180?'disabled':'')}</div>${state.coins>=180?'<p class="fine">钱包少于 180 金币时可以接取。目前可以先去完成普通订单。</p>':''}`}`;break}
case 'decorConfirm':{let d=CFG.decos.find(d=>d.id===modal.id);html=`<div class="deco-art">${Art.decor(d.id)}</div><h2>${d.name}</h2><div class="receipt"><div><span>装饰价格</span><strong>${d.price} 金币</strong></div><div><span>购买后钱包</span><strong>${state.coins-d.price} 金币</strong></div></div>${state.coins-d.price<180?'<p class="notice">购买后不足 180 金币，可用免费帮工补充启动资金。</p>':''}<div class="actions">${B('买下并布置','decorConfirm','',state.coins<d.price?'disabled':'')}${B('再看看','close','ghost')}</div>`;break}
case 'rename':{let p=state.products.find(p=>p.id===modal.id);html=`<h2>给作品一个名字</h2><div class="field"><input id="product-name" maxlength="12" value="${E(p.name)}" aria-label="作品名称"></div><p class="fine">最多 12 字。名字不会改变订单匹配和商品成本。</p><div class="actions">${B('保存名字','renameConfirm')}</div>`;break}
case 'import':{let s=modal.backup.state;html=`<h2>找回你的小铺故事</h2><p>先核对备份，再选择恢复的位置。</p><div class="receipt"><div><span>小掌柜</span><strong>${E(s.name)}</strong></div><div><span>金币</span><strong>${s.coins}</strong></div><div><span>备份日期</span><strong>${E(new Date(modal.backup.exported).toLocaleString('zh-CN'))}</strong></div></div><div class="field"><label for="import-slot">恢复到哪个存档</label><select id="import-slot">${[0,1,2].map(i=>{let x=null;try{x=load(i)}catch(e){}return `<option value="${i}">存档 ${i+1} · ${E(x?.name||'空存档')}${x?'（将覆盖此存档）':''}</option>`}).join('')}</select></div><p class="notice">如果选择已有存档，确认后将覆盖。建议先导出现有存档的备份。</p><div class="actions">${B('确认恢复到所选位置','importConfirm')}${B('取消','close','ghost')}</div>`;break}
case 'help':html=`<div class="eyebrow">WELCOME, LITTLE SHOPKEEPER</div><h2>在小镇，做一份喜欢的礼物。</h2><div class="math-details"><p><strong>在三维小镇里走一走</strong>　WASD / 方向键移动，点击地面或店铺自动寻路。走近店铺按 E 互动。手机可用左下角摇杆。</p><p>“跟随角色”看近景，“俯瞰小镇”看全景；右键拖动环顾，滚轮缩放。</p><p><strong>1 · 看订单</strong>　知道顾客想要什么。</p><p><strong>2 · 挑原石</strong>　先看价格，再算一算预算。</p><p><strong>3 · 切开它</strong>　沿着虚线划过，或点击辅助切割。</p><p><strong>4 · 做作品</strong>　选款式、外观与数量，按住宝石打磨，再点击工作台上的三枚金色配件进行装配。</p><p><strong>5 · 送出去</strong>　整单交付，看看这次赚了多少。</p></div><p>算术题答错不会扣钱，提示会一步步帮助你。金币不足 180 时，可以免费帮工。喜欢的作品可以在背包里留影收藏。</p><div class="actions">${B('知道啦，回到小镇','gotoTown')}</div><p class="fine">离线使用：下载 HTML，用桌面浏览器打开。浏览器限制本地存储时，请使用在线版并定期导出 JSON 备份。角色、店铺和商品由原创三维网格构成，音效为程序合成。支持 WebGL 的设备使用 Three.js 渲染；其他设备自动使用兼容三维画面。</p>`;break;
case 'confirmCancel':html=`<h2>暂时放下这份心愿？</h2><p>取消订单不会收走已经购买的原石、材料或作品。以后还可以重新接取。</p><div class="actions">${B('确认取消订单','confirmCancel')}${B('继续制作','close','ghost')}</div>`;break;
case 'history':html=`<h2>已经打开的惊喜</h2><p>这只是回看，不会扣费，也不会再次获得材料。</p><div class="inventory-grid" style="grid-template-columns:1fr 1fr;margin-top:20px">${state.raws.filter(r=>r.status==='cut').map(r=>`<div class="item-card"><div class="item-art">${G(r.mat,'material')}</div><h3>${CFG.materials[r.mat].name} · ${r.qty} 份</h3><p>${r.id} · 已切割</p></div>`).join('')}</div>`;break;
}}$('#modal-root').innerHTML=modal?`<div class="modal-backdrop"><section class="modal ${['receipt','cutResult','craftResult'].includes(modal.type)?'center':''} ${modal.type==='history'?'wide':''}" role="dialog" aria-modal="true" aria-label="${modal.type==='math'?'小算术':'游戏操作'}"><button class="close" data-action="close" aria-label="关闭">×</button>${html}</section></div>`:'';if(window.GemWorld)GemWorld.setModal(!!modal);if(modal)setTimeout(()=>{let f=$('.modal input:not([type=checkbox])')||$('.modal .btn');f?.focus({preventScroll:true})},0)}
async function go(p,arrived=false){if(!state){openModal({type:'start',slot:0,avatar:0});return}if(!ui.classic&&GemWorld.ready&&['market','cut','craft','sell'].includes(p)&&!arrived&&!GemWorld.at(p)){modal=null;ui.workGame=null;page='town';render();GemWorld.walkTo(p,true);return}modal=null;ui.workGame=null;page=p;ui.armed=false;if(!readOnly&&['town','market','cut','craft','sell'].includes(p))await run({type:'scene',scene:p,pose:!ui.classic?GemWorld.pose():null});render();window.scrollTo({top:0,behavior:'instant'})}
async function makeSave(guidance){let i=modal.slot,name=$('#nickname').value||'小掌柜',av=modal.avatar;assertSlotEmpty(i);let next=GemGame.create(name,av);next.settings.guidance=guidance;localStorage.setItem(KEY+i,JSON.stringify(next));release();slot=i;localStorage.setItem('gem-shop-active',String(i));state=next;page='town';modal=null;takeControl();render();tone('success');toast('小铺开张啦！1000 金币和第一张订单已准备好。')}
function assertSlotEmpty(i){if(localStorage.getItem(KEY+i))throw Error('该位置已有存档，请选择一个空位置。')}
function mathOpen(id,after=null){openModal({type:'math',id,after,input:''})}
async function continueMath(){let after=modal.after,q=state.exercises.find(q=>q.id===modal.id);if(!q.done)return;if(after?.type==='buy'){openModal({type:'buyConfirm',sku:after.sku})}else if(after?.type==='craft'){openModal({type:'craftConfirm',lot:after.lot})}else if(after?.type==='support'){await run({type:'finishSupport'});modal=null;render();tone('success');toast('帮工完成！80 金币到账。')}else{modal=null;render();toast('账单已收好，继续经营吧。')}}
function confetti(){if(!state?.settings.motion)return;for(let i=0;i<24;i++){let d=document.createElement('i');d.className='confetti';d.style.left=(15+Math.random()*70)+'%';d.style.background=['#d7856b','#9aaf80','#e1bf78','#aabed0'][i%4];d.style.animationDelay=Math.random()*.5+'s';d.style.transform='rotate('+Math.random()*100+'deg)';document.body.append(d);setTimeout(()=>d.remove(),2300)}}
function restoreUIFromDraft(){let ds=Object.values(state?.drafts||{}),buy=ds.find(d=>d.sku),craft=ds.find(d=>d.lot);if(buy){ui.sku=buy.sku;if(page==='market')ui.recipe=buy.recipe}if(craft){ui.lot=craft.lot;if(page==='craft')ui.recipe=craft.recipe;ui.qty=craft.qty;ui.style=craft.style;ui.name=craft.name}}
async function baseAction(a,el){switch(a){
case 'start':{let empty=[0,1,2].find(i=>!localStorage.getItem(KEY+i));openModal(empty===undefined?{type:'slots'}:{type:'start',slot:empty,avatar:0});break}
case 'createSave':await makeSave(true);break;case 'createSolo':await makeSave(false);break;
case 'avatar':{let name=$('#nickname')?.value;modal.avatar=Number(el.dataset.index);renderModal();$('#nickname').value=name||'';break}
case 'slots':openModal({type:'slots'});break;
case 'selectSlot':{ui.workGame=null;ui.armed=false;let i=Number(el.dataset.index),s=load(i);if(s){release();slot=i;state=s;localStorage.setItem('gem-shop-active',String(i));page=s.scene;modal=null;takeControl();restoreUIFromDraft();render();music()}else openModal({type:'start',slot:i,avatar:i});break}
case 'takeControl':{state=load(slot);takeControl(true);render();toast('已载入最新存档，可以继续操作。');break}
case 'close':closeModal();break;
case 'help':openModal({type:'help'});break;
case 'next':{let n=nextStep();if(n.page==='market'){let o=state.orders.find(o=>o.status==='active'),r=CFG.recipes.find(r=>r.id===o?.recipe);if(r){ui.sku=CFG.raws.find(a=>a.mat===r.mat).id;ui.recipe=r.id}}else if(n.page==='craft'){let o=state.orders.find(o=>o.status==='active'),r=CFG.recipes.find(r=>r.id===o?.recipe);if(r){ui.recipe=r.id;ui.lot=state.lots.find(l=>l.mat===r.mat&&l.groups*l.group>=r.use)?.id;ui.qty=o.qty}}await go(n.page);break}
case 'gotoTown':await go('town');break;case 'gotoMarket':await go('market');break;case 'gotoCut':await go('cut');break;case 'gotoCraft':await go('craft');break;case 'gotoSell':await go('sell');break;case 'gotoOrders':ui.tab='all';await go('orders');break;
case 'selectSku':{let r=CFG.raws.find(r=>r.id===el.dataset.id);if(!state.tutorialTrade&&r.id!=='R-AG'){toast('第一张订单完成后，这个摊位就开放啦。');break}ui.sku=r.id;ui.recipe=state.drafts['buy:'+r.id]?.recipe||null;ui.rotation=0;render();break}
case 'rotate':ui.rotation=(ui.rotation+45)%360;render();break;case 'shape':ui.shape=Number(el.dataset.value);render();break;
case 'buyPrepare':{let r=CFG.raws.find(r=>r.id===ui.sku),p=CFG.recipes.find(r=>r.id===ui.recipe),d=await run({type:'prepareBuy',sku:r.id,recipe:p.id,qty:Math.floor(r.qty/p.use)}),q=state.exercises.find(q=>q.id===d.q);if(q.done)openModal({type:'buyConfirm',sku:r.id});else mathOpen(q.id,{type:'buy',sku:r.id});break}
case 'buyConfirm':{let sku=modal.sku,d=state.drafts['buy:'+sku],res=await run({type:'buy',sku,request:d.request,shape:ui.shape});ui.raw=res.raw;modal=null;page=ui.classic?'cut':'town';ui.armed=false;render();if(!ui.classic)GemWorld.walkTo('cut',true);tone('success');toast('原石收好啦！带着它走到切割工坊。');break}
case 'digit':{let inp=$('#math-answer'),v=el.dataset.value;inp.value=v==='清空'?'':v==='⌫'?inp.value.slice(0,-1):(inp.value+v).slice(0,9);modal.input=inp.value;break}
case 'mathSubmit':{modal.input=$('#math-answer').value;let r=await run({type:'answer',id:modal.id,value:modal.input});if(r.correct){tone('success');modal.feedback=''}else{tone('error');modal.feedback='还差一点点。看看已知条件，也可以打开提示。'}renderModal();break}
case 'mathHint':{modal.input=$('#math-answer')?.value||'';await run({type:'hint',id:modal.id});renderModal();break}
case 'mathDemo':await run({type:'demo',id:modal.id});renderModal();break;
case 'mathContinue':await continueMath();break;
case 'selectRaw':ui.raw=el.dataset.id;ui.armed=false;render();break;
case 'direction':ui.direction=el.dataset.value;render();break;
case 'armCut':ui.armed=true;render();break;
case 'unarm':ui.armed=false;render();break;
case 'assistCut':await finishCut();break;
case 'selectRecipe':ui.recipe=el.dataset.id;ui.name='';ui.style='classic';ui.qty=1;render();break;
case 'style':ui.style=el.dataset.value;render();break;
case 'craftPrepare':{ui.name=$('#craft-name')?.value||'';ui.qty=Number($('#craft-qty').value);let d=await run({type:'prepareCraft',lot:ui.lot,recipe:ui.recipe,qty:ui.qty,style:ui.style,name:ui.name});let q=state.exercises.find(q=>q.id===d.q);if(q.done)openModal({type:'craftConfirm',lot:d.lot});else mathOpen(q.id,{type:'craft',lot:d.lot});break}
case 'craftConfirm':{let d=state.drafts['craft:'+modal.lot],style=d.style,qty=d.qty;let res=await run({type:'craft',lot:d.lot,request:d.request});modal={type:'craftResult',recipe:res.recipe,items:res.items,style,qty};render();tone('success');confetti();break}
case 'accept':await run({type:'accept',template:el.dataset.id});tone('success');toast('心愿接好啦，可以慢慢准备。');render();break;
case 'cancelOrder':openModal({type:'confirmCancel',id:el.dataset.id});break;
case 'confirmCancel':await run({type:'cancelOrder',order:modal.id});modal=null;render();toast('订单已取消，背包里的物品都保留。');break;
case 'forOrder':{let o=state.orders.find(o=>o.id===el.dataset.id),r=CFG.recipes.find(r=>r.id===o.recipe),l=state.lots.find(l=>l.mat===r.mat&&l.groups*l.group>=r.use),raw=state.raws.find(a=>a.mat===r.mat&&a.status==='raw');ui.recipe=r.id;ui.qty=o.qty;if(l){ui.lot=l.id;await go('craft')}else if(raw){ui.raw=raw.id;await go('cut')}else{ui.sku=CFG.raws.find(a=>a.mat===r.mat).id;await go('market')}break}
case 'sellPrepare':{let o=state.orders.find(o=>o.id===el.dataset.id),items=state.products.filter(p=>p.recipe===o.recipe&&p.status!=='sold').slice(0,o.qty).map(p=>p.id);openModal({type:'sellConfirm',order:o.id,items,request:'sell-'+o.id});break}
case 'sellConfirm':{let o=state.orders.find(o=>o.id===modal.order),customer=CFG.orders.findIndex(t=>t.id===o.template)%4;let res=await run({type:'sell',order:o.id,items:modal.items,request:modal.request});modal={...res,type:'receipt',customer};render();tone('success');confetti();break}
case 'receiptMath':mathOpen(modal.q);break;
case 'pendingMath':{let q=state.exercises.find(q=>q.slot==='Q3'&&!q.done);if(q)mathOpen(q.id);else toast('所有账单都看懂啦。');break}
case 'refreshRecommendations':ui.recommend=(ui.recommend+2)%7;render();break;
case 'orderTab':ui.tab=el.dataset.value;render();break;case 'bagTab':ui.bagTab=el.dataset.value;render();break;case 'galleryTab':ui.galleryTab=el.dataset.value;render();break;
case 'bagCut':ui.raw=el.dataset.id;await go('cut');break;case 'bagCraft':ui.lot=el.dataset.id;ui.recipe=null;await go('craft');break;
case 'collect':await run({type:'collect',id:el.dataset.id});render();toast('作品留影已放入图鉴，实体仍可正常出售。');break;
case 'collectResult':for(let id of modal.items)await run({type:'collect',id});toast('留影完成！可以放心交付给顾客啦。');break;
case 'rename':openModal({type:'rename',id:el.dataset.id});break;
case 'renameConfirm':await run({type:'nameProduct',id:modal.id,name:$('#product-name').value});modal=null;render();toast('作品名字保存好了。');break;
case 'decorPrepare':{let id=el.dataset.id;if(state.owned.includes(id)){await run({type:'decor',id});render();toast('小镇装饰已更新。')}else openModal({type:'decorConfirm',id});break}
case 'decorConfirm':await run({type:'decor',id:modal.id,request:'decor-'+modal.id});modal=null;render();tone('success');toast('装饰已布置到小镇。');break;
case 'toggleSetting':await run({type:'settings',values:{[el.dataset.key]:!state.settings[el.dataset.key]}});render();music();break;
case 'support':openModal({type:'support'});break;
case 'startSupport':await run({type:'startSupport'});renderModal();break;
case 'makeSupport':await run({type:'makeSupport'});tone('success');toast('两条手链串好啦，来算算数量。');renderModal();break;
case 'supportMath':{let q=state.exercises.find(q=>q.id===state.support.q);if(q.done){await run({type:'finishSupport'});modal=null;render();toast('帮工完成，80 金币到账。');tone('success')}else mathOpen(q.id,{type:'support'});break}
case 'cancelSupport':await run({type:'cancelSupport'});modal=null;render();toast('委托已取消，没有花费金币。');break;
case 'export':{let backup={game:'gem-little-shop',schema:1,config:CFG.version,exported:new Date().toISOString(),state};download(JSON.stringify(backup,null,2),'宝石小掌柜_存档'+(slot+1)+'_'+new Date().toISOString().slice(0,10)+'.json','application/json');toast('备份已开始下载，请保留好这份小铺故事。');break}
case 'import':$('#import-file').value='';$('#import-file').click();break;
case 'importConfirm':{let target=Number($('#import-slot').value),s=JSON.parse(JSON.stringify(modal.backup.state));GemGame.validate(s);let key=KEY+target,l=JSON.parse(localStorage.getItem(key+'-lease')||'null');if(l&&l.owner!==OWNER&&Date.now()-l.time<LEASE)throw Error('目标存档正在另一页面使用，请先关闭那个页面。');let previous=null;try{previous=load(target)}catch(_){}s.revision=Math.max(s.revision,previous?.revision||0)+1;s.updated=Date.now();s.id='save-restored-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);localStorage.setItem(key,JSON.stringify(s));release();slot=target;state=s;localStorage.setItem('gem-shop-active',String(slot));takeControl(true);modal=null;page='town';render();toast('存档恢复成功，欢迎回来。');break}
case 'cutHistory':openModal({type:'history'});break;
}}
function download(data,name,type){let url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000)}
async function finishCut(){if(!ui.armed)return;let raw=ui.raw;ui.armed=false;try{let res=await run({type:'cut',raw,valid:true,request:'cut-'+raw});ui.lot=res.lot;let wanted=state.orders.find(o=>o.status==='active'&&CFG.recipes.find(r=>r.id===o.recipe)?.mat===res.mat);ui.recipe=wanted?.recipe||null;ui.qty=wanted?.qty||1;modal={type:'cutResult',...res};render();if(!ui.classic)GemWorld.effect('cut',res.mat);tone('success');confetti()}catch(e){render()}}
function bindCut(){let guide=$('#cut-guide');if(!guide)return;let points=[],start=null;function pos(e){let b=guide.getBoundingClientRect();return{x:(e.clientX-b.left)/b.width*100,y:(e.clientY-b.top)/b.height*100}}let A={x:25,y:ui.direction==='horizontal'?50:70},B={x:75,y:ui.direction==='horizontal'?50:30};const dist=(p,q)=>Math.hypot(p.x-q.x,p.y-q.y);guide.addEventListener('pointerdown',e=>{if(!ui.armed){toast('先确认切割费用，再开始划线。');return}let p=pos(e);if(Math.min(dist(p,A),dist(p,B))>12){toast('从虚线一端的圆点开始，慢慢划过去。');return}start=dist(p,A)<dist(p,B)?A:B;points=[p];guide.setPointerCapture(e.pointerId)});guide.addEventListener('pointermove',e=>{if(!start)return;points.push(pos(e));if(!ui.classic)GemWorld.cutProgress(Math.max(0,Math.min(1,(points.at(-1).x-25)/50)));$('#cut-trail')?.setAttribute('d',points.map((p,i)=>(i?'L':'M')+p.x+' '+p.y).join(' '))});guide.addEventListener('pointerup',async e=>{if(!start)return;points.push(pos(e));let end=start===A?B:A,valid=dist(points.at(-1),end)<12&&points.length>=2&&points.every(p=>Math.abs((B.y-A.y)*p.x-(B.x-A.x)*p.y+B.x*A.y-B.y*A.x)/dist(A,B)<13);start=null;if(valid)await finishCut();else{toast('再试一下：沿虚线，从一个圆点划到另一个圆点。没有扣费。');$('#cut-trail')?.setAttribute('d','')}});guide.addEventListener('pointercancel',()=>{start=null;points=[];$('#cut-trail')?.setAttribute('d','')})}
document.addEventListener('click',async e=>{let btn=e.target.closest('button');if(!btn||btn.disabled||busy)return;try{if(btn.dataset.page){tone();await go(btn.dataset.page)}else if(btn.dataset.action){tone();await handleAction(btn.dataset.action,btn)}}catch(e){if(!saveError)toast(e.message,true)}});
document.addEventListener('input',e=>{if(e.target.id==='craft-name')ui.name=e.target.value;if(e.target.id==='math-answer'&&modal)modal.input=e.target.value});
document.addEventListener('change',async e=>{try{switch(e.target.id){case 'buy-recipe':ui.recipe=e.target.value;render();break;case 'craft-lot':ui.lot=e.target.value;ui.recipe=null;ui.qty=1;ui.name='';render();break;case 'craft-qty':ui.qty=Math.max(1,Math.floor(Number(e.target.value)||1));ui.name=$('#craft-name').value;render();break;case 'difficulty':await run({type:'settings',values:{difficulty:e.target.value}});toast('难度已更新，从下一道新题生效。');render();break;case 'import-file':{let f=e.target.files[0];if(!f)break;if(f.size>2*1024*1024)throw Error('备份文件不能超过 2 MiB');let data=JSON.parse(await f.text());if(data.game!=='gem-little-shop'||data.schema!==1||!data.exported)throw Error('这不是兼容的宝石小掌柜备份');GemGame.validate(data.state);openModal({type:'import',backup:data});break}}
if(e.target.dataset.item&&modal?.type==='sellConfirm'){let id=e.target.dataset.item;modal.items=e.target.checked?[...modal.items,id]:modal.items.filter(x=>x!==id);renderModal()}}catch(e){toast('操作未保存：'+e.message,true)}});
document.addEventListener('keydown',async e=>{if(e.key==='Escape'&&modal){closeModal();return}if(e.key==='Enter'&&modal?.type==='math'&&!state.exercises.find(q=>q.id===modal.id).done){e.preventDefault();try{await handleAction('mathSubmit',{})}catch(_){}}if(e.key==='Tab'&&modal){let fs=[...document.querySelectorAll('.modal button:not(:disabled),.modal input,.modal select')],first=fs[0],last=fs.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}});

// 3D presentation uses the same inventory, transactions and storage as the original game.
const flatTown=town;
town=function(){if(ui.classic)return flatTown();let o=state?.orders.find(o=>o.status==='active'),r=CFG.recipes.find(r=>r.id===o?.recipe),n=nextStep();return head(state?'小掌柜，出门逛逛吧。':'走进你的宝石小镇。','WELCOME TO YOUR 3D GEM VILLAGE','走到小屋前，与摊主聊聊，把一块原石变成一份礼物。',`<span class="pill">${I('sun','sm')}可自由行走的三维小镇</span>`)+`<div class="world-stage" id="town-stage"><div id="world-mount" class="world-mount"></div><div class="world-hud world-toolbar"><button class="${ui.view==='overview'?'active':''}" data-action="cameraOverview">${I('town','sm')} 俯瞰小镇</button><button class="${ui.view==='follow'?'active':''}" data-action="cameraFollow">${I('leaf','sm')} 跟随角色</button><button data-action="worldNight">${ui.night?'白天':'暖夜'}</button><button data-action="worldQuality" id="world-quality">${ui.lowQuality?'流畅画质':'精细画质'}</button></div><div class="world-hud world-status"><i></i><span id="world-location">宝石广场</span></div><section class="world-hud world-quest"><h3>${I('orders','sm')}${o?'手中的小心愿':'今天，做点什么？'}</h3>${o?`<p>${E(o.who)}正在等你的手工作品</p><div class="wish"><div class="wish-art">${G(r.mat,r.kind)}</div><div><strong>${r.name} × ${o.qty}</strong><span class="small-tag">整单收入 ${o.price*o.qty} 金币</span></div></div><div class="tiny-progress"><span style="width:${n.index/3*100}%"></span></div><p>采购 → 切割 → 加工 → 交付</p>${B('带我去'+({market:'原石集市',cut:'切割工坊',craft:'手作工坊',sell:'宝石小铺'}[n.page]||'订单板')+' →','next','full small','style="margin-top:12px"')}`:state?`<p>散散步，看看摊位，或者接下新的顾客心愿。</p>${B('看看新的顾客心愿','gotoOrders','full small','style="margin-top:12px"')}`:`<p>你的第一家宝石小铺，正等待开张。给角色起个名字，开始小镇生活。</p>${B('创建小掌柜，开始冒险','start','full small','style="margin-top:12px"')}`}${state?.exercises.some(q=>q.slot==='Q3'&&!q.done)?'<button class="text-btn" data-action="pendingMath">看懂上次的账单 →</button>':''}</section><div class="world-hud world-bottom"><div class="world-guide"><div class="key-row"><span><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> 行走</span><span><kbd>E</kbd> 互动</span></div><small>点击地面自动走过去 · 右键拖动环顾 · 滚轮缩放</small></div><div class="joystick" id="world-joystick" aria-label="触屏摇杆"><i class="stick"></i></div></div><button class="nearby-action" id="nearby-action" data-action="worldInteract" hidden></button><div class="world-hud world-mini"><div class="mini-title">GEM VILLAGE</div><div class="mini-map"><i class="mini-shop a"></i><i class="mini-shop b"></i><i class="mini-shop c"></i><i class="mini-shop d"></i><i id="mini-player" class="mini-player"></i></div></div></div><div class="world-nav">${[['market','原石集市','01'],['cut','切割工坊','02'],['craft','手作工坊','03'],['sell','宝石小铺','04']].map(([p,n,i])=>`<button data-page="${p}"><b>${i}</b>${n}<small>走过去 →</small></button>`).join('')}<button data-action="help">操作说明 ${I('help','sm')}</button></div>`};
function stationView(id){let info=GemWorld.stationInfo[id];return `<div class="world-stage station"><div id="world-mount" class="world-mount"></div><div class="world-title">${info.name} / ${info.npc}</div><div class="merchant-note"><strong>${info.npc}</strong>${info.greeting}</div></div>`}
function workPanel(){let g=ui.workGame,pct=Math.round(g.progress*100),done=g.installed.length===3;return `<aside class="panel work-process"><div class="step-line"><span class="${g.stage==='polish'?'active':''}">01 打磨</span>→<span class="${g.stage==='assemble'&&!done?'active':''}">02 装配</span>→<span class="${done?'active':''}">03 完成</span></div><h3>${g.stage==='polish'?'把宝石打磨到发亮。':done?'你的手工作品完成啦。':'把配件安装到作品上。'}</h3><p class="sub">${g.stage==='polish'?'按住三维宝石并拖动，慢慢打磨它的表面。':'点击工作台上三处金色配件，逐个装到作品上。'}</p>${g.stage==='polish'?`<div class="work-percent"><span id="polish-number">${pct}</span><small>%</small></div><div class="work-progress"><span id="polish-progress" style="width:${pct}%"></span></div><p class="fine" id="polish-message">${pct===100?'摸起来光滑，颜色也更通透了。':'按住宝石约 4 秒，也可以拖动观察不同角度。'}</p>${B('打磨好了，开始装配 →','workNext','full','id="work-next" '+(pct<100?'disabled':''))}<button class="text-btn" data-action="assistPolish">需要帮助？辅助完成打磨</button>`:`<div class="parts-list">${[0,1,2].map(i=>`<div class="${g.installed.includes(i)?'done':''}"><b>${g.installed.includes(i)?'✓':i+1}</b>配件 ${i+1}</div>`).join('')}</div>${B(done?'确认完成 '+ui.qty+' 件作品':'请先装好三处配件','finishWork','full',done?'':'disabled')}<button class="text-btn" data-action="assistAssemble" ${done?'disabled':''}>辅助安装下一处配件</button>`}<div class="work-feedback">材料和加工费会在确认作品完成后一次结算。现在退出不会损失材料。</div><button class="work-cancel" data-action="cancelWork">暂时停下，返回制作方案</button></aside>`}
function decorate3D(p,html){if(ui.classic||!['market','cut','craft','sell'].includes(p))return html;let temp=document.createElement('div');temp.innerHTML=html;if(p==='market'){let section=temp.querySelector('.workspace>section');if(section)section.innerHTML=stationView(p)+`<div class="stone-strip">${CFG.raws.map((r,i)=>`<button class="stone-mini ${ui.sku===r.id?'selected':''} ${!state.tutorialTrade&&i>0?'locked':''}" data-action="selectSku" data-id="${r.id}"><strong><i style="background:${CFG.materials[r.mat].color}"></i>${r.name}</strong><small>${r.price} 金币 · ${r.qty} 份</small></button>`).join('')}</div><p class="fine">直接点击柜台上的原石也可以挑选。购买后，小掌柜会抱着原石走向切割工坊。</p>`;}
if(p==='cut'||p==='craft'){let bench=temp.querySelector('.workbench');if(bench){bench.querySelector('.main-gem')?.remove();bench.insertAdjacentHTML('afterbegin','<div id="world-mount" class="world-mount"></div>');if(p==='cut'&&!ui.armed){bench.querySelector('.cut-guide').style.pointerEvents='none';bench.querySelector('.cut-guide').style.opacity='.4'}if(p==='craft'&&ui.workGame){let workspace=temp.querySelector('.workspace'),section=workspace.querySelector('section');section.innerHTML=`<div class="workbench crafting"><div id="world-mount" class="world-mount"></div><span class="bench-label">${ui.workGame.stage==='polish'?'手动打磨 / 按住宝石':'手动装配 / 点击金色配件'}</span><span class="work-scene-note">${ui.workGame.stage==='polish'?'按住并拖动':'依次安装三处配件'}</span></div>`;workspace.querySelector('aside').outerHTML=workPanel();}}else{let empty=temp.querySelector('.panel');if(empty)empty.insertAdjacentHTML('beforebegin',stationView(p));}}
if(p==='sell'){let grid=temp.querySelector('.orders-grid');if(grid){let wrap=document.createElement('div');wrap.className='workspace world-shop-sell';grid.before(wrap);wrap.innerHTML=stationView(p);wrap.append(grid)}}return temp.innerHTML;}
function attachWorld(){let mount=ui.classic?null:$('#world-mount');GemWorld.mount(mount,{page,state,ui,modal:!!modal,onEnter:id=>go(id,true).catch(e=>toast(e.message,true)),onSelectSku:id=>handleAction('selectSku',{dataset:{id}}).catch(e=>toast(e.message,true)),onHint:msg=>{let el=$('#world-location');if(el)el.textContent=msg},onWalkEnd:()=>{},onPolish:value=>{if(!ui.workGame)return;ui.workGame.progress=value;let pct=Math.round(value*100);let n=$('#polish-number'),bar=$('#polish-progress'),button=$('#work-next');if(n)n.textContent=pct;if(bar)bar.style.width=pct+'%';if(button)button.disabled=value<1;if(value>=1){let note=$('#polish-message');if(note)note.textContent='打磨完成，可以开始安装配件了。'}},onSocket:i=>{if(!ui.workGame||ui.workGame.stage!=='assemble'||ui.workGame.installed.includes(i))return;ui.workGame.installed.push(i);tone('success');render()}});let joy=$('#world-joystick');if(joy){let stick=joy.querySelector('.stick'),held=false;function move(e){let r=joy.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/34,z=(e.clientY-r.top-r.height/2)/34,l=Math.max(1,Math.hypot(x,z));x/=l;z/=l;GemWorld.joystick(x,z);stick.style.transform=`translate(${x*24}px,${z*24}px)`}joy.addEventListener('pointerdown',e=>{held=true;joy.setPointerCapture(e.pointerId);move(e)});joy.addEventListener('pointermove',e=>{if(held)move(e)});for(let ev of ['pointerup','pointercancel'])joy.addEventListener(ev,()=>{held=false;stick.style.transform='';GemWorld.joystick(0,0)})}}
async function handleAction(a,el){if(a==='classicView'){ui.classic=true;render();toast('已切换兼容界面，存档和金币保持不变。');return}if(a==='cameraOverview'||a==='cameraFollow'){ui.view=a==='cameraOverview'?'overview':'follow';GemWorld.setView(ui.view);render();return}if(a==='worldNight'){ui.night=!ui.night;GemWorld.setNight(ui.night);render();return}if(a==='worldQuality'){ui.lowQuality=!ui.lowQuality;GemWorld.setQuality(ui.lowQuality);render();return}if(a==='worldInteract'){GemWorld.interact();return}if(a==='rotate'&&!ui.classic){GemWorld.rotateStone();await baseAction(a,el);return}
if(a==='craftConfirm'&&!ui.classic){ui.workGame={stage:'polish',progress:0,installed:[],lot:modal.lot};modal=null;render();toast('现在轮到你动手啦：按住工作台上的宝石进行打磨。');return}
if(a==='workNext'){if(ui.workGame?.progress<1)return;ui.workGame.stage='assemble';render();return}if(a==='assistPolish'){ui.workGame.progress=1;render();tone('success');return}if(a==='assistAssemble'){let next=[0,1,2].find(i=>!ui.workGame.installed.includes(i));if(next!==undefined)ui.workGame.installed.push(next);render();tone('success');return}if(a==='cancelWork'){ui.workGame=null;render();return}if(a==='finishWork'){if(ui.workGame?.installed.length!==3)return;let lot=ui.workGame.lot;ui.workGame=null;modal={type:'craftConfirm',lot};await baseAction('craftConfirm',el);return}
if(a==='sellConfirm'&&!ui.classic){let o=state.orders.find(o=>o.id===modal.order),customer=CFG.orders.findIndex(t=>t.id===o.template)%4;let res=await run({type:'sell',order:o.id,items:modal.items,request:modal.request});modal=null;render();GemWorld.effect('sell');tone('success');toast('小掌柜正在把礼物交给顾客。');setTimeout(()=>{if(page==='sell'&&!modal){modal={...res,type:'receipt',customer};render();confetti()}},1300);return}return baseAction(a,el)}

try{state=load(slot);if(state){page=state.scene||'town';takeControl();restoreUIFromDraft()}render();if(state?.settings.music)music()}catch(e){state=null;page='town';saveError='存档需要恢复';render();toast('无法读取当前存档：'+e.message+'。请在设置中选择另一存档或恢复备份。',true)}
